"""Small maintained documentation used by the UI and assistant; no provider call."""
TOPICS = [
    {'id':'getting-started','title':'Getting started','category':'Workspace','body':'Save your company profile, choose your objectives and create an ideal customer profile. Setup does not start discovery or email. Organization settings belong to the selected workspace; personal account details are separate.','href':'/onboarding'},
    {'id':'icp','title':'Create an ideal customer profile','category':'Prospecting','body':'Define industries, markets, company characteristics and decision-maker roles. Where AI is configured, generate suggested segments from your saved business profile or describe your audience. Review assumptions and edit before saving. Activation does not start discovery.','href':'/settings/icp'},
    {'id':'discovery','title':'Run a reviewed discovery search','category':'Prospecting','body':'Choose Search with AI, Search with Filters or Import Leads. Review geography, source coverage, result targets and resource limits before starting. A selected ICP guides fit; some criteria require evidence after discovery. Source coverage varies by location and category.','href':'/find-leads'},
    {'id':'company-results','title':'Understand company results','category':'Prospecting','body':'Company records combine discovery evidence and lightweight public website information. Fit and evidence coverage are separate. Missing observations remain unknown. Contact availability and email-send eligibility are separate from company qualification.','href':'/leads'},
    {'id':'contacts','title':'Professional contacts and verification','category':'Prospecting','body':'Contacts require a real name and an associated company. Public employment evidence is not an independent employment check. Syntax and DNS/MX checks do not prove that a mailbox accepts delivery. Changed email addresses need new checks.','href':'/contacts'},
    {'id':'enrichment','title':'Enrichment and resource limits','category':'Prospecting','body':'Explicit enrichment jobs reuse fresh evidence and check a bounded set of public pages. Review selected records before starting. Job history shows progress and failures. Enrichment does not send messages or run vulnerability, SEO or performance assessments.','href':'/enrichment'},
    {'id':'lists','title':'Organize companies and contacts into lists','category':'Sales','body':'Create a named list, then add companies and professional contacts. Membership is workspace-specific. Export is bounded and protects spreadsheet cells from formula execution. Archiving retains membership and history.','href':'/lists'},
    {'id':'tasks','title':'Manage tasks and follow-ups','category':'Sales','body':'Create an internal research, review or follow-up task for a stored company and optionally a contact. Assign a current workspace member, choose a priority and due date. Edit, complete or reopen tasks. Tasks never send email automatically. Suppression still protects outreach follow-ups.','href':'/tasks'},
    {'id':'campaigns','title':'Prepare campaigns and outreach','category':'Sales','body':'Campaigns group company records. Outreach uses an explicit campaign audience and a workspace-owned email template. Review exact messages and sending protections before starting. Gmail sign-in alone does not connect a sender. Rate limits, send windows and suppression still apply.','href':'/campaigns'},
    {'id':'connections','title':'Workspace connections','category':'Integrations','body':'A workspace owner or administrator connects supported providers separately from sign-in. Permissions are limited to approved scopes. A disconnected connection cannot be used for new imports or reads. Customer mailbox and CRM availability depend on implemented provider support and configuration.','href':'/settings/integrations'},
    {'id':'account-security','title':'Account access and security','category':'Account','body':'Use your permitted verified Google account. Public self-service signup is unavailable in this development release. Workspace roles control access. Do not share sign-in sessions, API keys or provider credentials. For account access issues, contact support or your workspace owner.','href':'/account/security'},
    {'id':'billing','title':'Usage and plan questions','category':'Account','body':'Configured safety limits bound discovery, enrichment and AI work. These are not a paid subscription or billing statement. Contact support about available plans; self-service billing is not claimed where it is unavailable.','href':'/settings'},
]


def search(query='',limit=5):
    from app.config.settings import get_settings
    topics=TOPICS if get_settings().lead_engine_available else RADAR_TOPICS
    terms=query.casefold().split()[:15]
    ranked=sorted(topics,key=lambda item:sum(term in (item['title']+' '+item['body']).casefold() for term in terms),reverse=True)
    return [item for item in ranked if not terms or any(term in (item['title']+' '+item['body']).casefold() for term in terms)][:limit]

